class Solution:
    def numberOfStableArrays(self, zero: int, one: int, limit: int) -> int:
        MOD = 10**9 + 7

        # dp[i][j][last][run] = number of ways to have i zeros, j ones, 
        # ending with 'last' (0 or 1) with consecutive count 'run'
        # We'll use a 4D array with dimensions (zero+1) x (one+1) x 2 x (limit+1)

        # Initialize DP table
        dp = [[[[0 for _ in range(limit + 1)] for _ in range(2)] for _ in range(one + 1)] for _ in range(zero + 1)]

        # Base cases: we can start with either a 0 or a 1
        if zero > 0:
            dp[1][0][0][1] = 1
        if one > 0:
            dp[0][1][1][1] = 1

        # Fill the DP table
        for i in range(zero + 1):
            for j in range(one + 1):
                for last in range(2):
                    for run in range(1, limit + 1):
                        if dp[i][j][last][run] == 0:
                            continue

                        # Try to add a zero
                        if i > 0:
                            # If last was 0, we extend the run
                            if last == 0:
                                if run < limit:
                                    dp[i-1][j][0][run+1] = (dp[i-1][j][0][run+1] + dp[i][j][last][run]) % MOD
                            else:  # last was 1
                                # Starting a new run of zeros
                                dp[i-1][j][0][1] = (dp[i-1][j][0][1] + dp[i][j][last][run]) % MOD

                        # Try to add a one
                        if j > 0:
                            if last == 1:
                                if run < limit:
                                    dp[i][j-1][1][run+1] = (dp[i][j-1][1][run+1] + dp[i][j][last][run]) % MOD
                            else:  # last was 0
                                dp[i][j-1][1][1] = (dp[i][j-1][1][1] + dp[i][j][last][run]) % MOD

        # Sum all valid final states
        result = 0
        for last in range(2):
            for run in range(1, limit + 1):
                result = (result + dp[zero][one][last][run]) % MOD

        return result

