class Solution:
    def numberOfStableArrays(self, zero: int, one: int, limit: int) -> int:
        MOD = 10**9 + 7

        from functools import lru_cache

        @lru_cache(maxsize=None)
        def dp(zeros_used, ones_used, last, consec):
            # If we've used all needed zeros and ones
            if zeros_used == zero and ones_used == one:
                return 1

            # If we've exceeded the required counts
            if zeros_used > zero or ones_used > one:
                return 0

            result = 0

            # Try placing a 0
            if zeros_used < zero:
                if last == 0:
                    # Can only place if consecutive count < limit
                    if consec < limit:
                        result = (result + dp(zeros_used + 1, ones_used, 0, consec + 1)) % MOD
                else:
                    # Place a 0 (start new sequence)
                    result = (result + dp(zeros_used + 1, ones_used, 0, 1)) % MOD

            # Try placing a 1
            if ones_used < one:
                if last == 1:
                    if consec < limit:
                        result = (result + dp(zeros_used, ones_used + 1, 1, consec + 1)) % MOD
                else:
                    result = (result + dp(zeros_used, ones_used + 1, 1, 1)) % MOD

            return result

        # The total is the sum of all valid sequences
        # We can start with either 0 or 1
        total = 0

        # Start with 0
        if zero > 0:
            total = (total + dp(1, 0, 0, 1)) % MOD

        # Start with 1
        if one > 0:
            total = (total + dp(0, 1, 1, 1)) % MOD

        return total

