    base = (M - 1) % MOD
    power_term = mod_pow(base, N, MOD)

    # Calculate (-1)^N * (M-1)
    if N % 2 == 0:
        sign_term = (M - 1) % MOD
    else:
        sign_term = (MOD - (M - 1)) % MOD  # This is equivalent to -(M-1) mod MOD

